import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-06-03","description":"","frontmatter":{"date":"2026-06-03T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-06-03-uxtrend.md","filePath":"daily/2026-06-03-uxtrend.md"}'),n={name:"daily/2026-06-03-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-06-03" tabindex="-1">设计趋势 - 2026-06-03 <a class="header-anchor" href="#设计趋势-2026-06-03" aria-label="Permalink to &quot;设计趋势 - 2026-06-03&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI工作流优化和用户体验设计。主要动态包括：1) 7个实用技巧提升AI工作流效率；2) AI代理工作流设计模式的探讨；3) AI工具V0在产品原型设计中的应用；4) 代理型用户体验设计指南；5) 提示工程作为新兴用户体验技能。最值得关注的是AI工具V0在产品原型设计中的快速应用，以及提示工程对AI用户体验的改善。</p><hr><h3 id="_1-ai工作流优化-7个实用技巧" tabindex="-1">1. AI工作流优化：7个实用技巧 <a class="header-anchor" href="#_1-ai工作流优化-7个实用技巧" aria-label="Permalink to &quot;1. AI工作流优化：7个实用技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">AI Workflow Optimization: 7 Game-Changing Tips That Actually Work</a></p><p><strong>一句话摘要</strong>: 通过定制AI提示和工具，优化设计工作流程。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少重复性工作。</p><p><strong>产品应用</strong>: 适用于需要快速迭代设计概念的产品开发。</p><p><strong>示例场景</strong>: 使用AI工具生成布局结构和配色方案。</p><hr><h3 id="_2-ai代理工作流设计模式概览" tabindex="-1">2. AI代理工作流设计模式概览 <a class="header-anchor" href="#_2-ai代理工作流设计模式概览" aria-label="Permalink to &quot;2. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，包括ReAct和Plan-Solve模式。</p><p><strong>能解决什么问题</strong>: 如何设计灵活的工作流以应对不同的AI代理任务。</p><p><strong>产品应用</strong>: 可应用于开发AI代理，通过工作流模式灵活处理问题。</p><p><strong>示例场景</strong>: 设计一个AI代理，通过工作流模式完成复杂任务。</p><hr><h3 id="_3-产品设计师的ai设计工作流程" tabindex="-1">3. 产品设计师的AI设计工作流程 <a class="header-anchor" href="#_3-产品设计师的ai设计工作流程" aria-label="Permalink to &quot;3. 产品设计师的AI设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@mariamargarida/ai-in-my-design-workflow-as-a-product-designer-feb120d8fe38" target="_blank" rel="noreferrer">AI In My Design Workflow As a Product Designer</a></p><p><strong>一句话摘要</strong>: AI工具V0在快速原型设计和交互演示中的应用。</p><p><strong>能解决什么问题</strong>: 解决复杂流程设计中的效率和直观性问题。</p><p><strong>产品应用</strong>: 适用于需要快速迭代和演示的产品设计流程。</p><p><strong>示例场景</strong>: 使用V0快速构建和测试滚动行为和过渡效果。</p><hr><h3 id="_4-为代理型用户体验设计指南" tabindex="-1">4. 为代理型用户体验设计指南 <a class="header-anchor" href="#_4-为代理型用户体验设计指南" aria-label="Permalink to &quot;4. 为代理型用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 通过规则、行为、触发器和例外设计智能代理体验。</p><p><strong>能解决什么问题</strong>: 解决如何使智能代理更自然地融入用户日常生活的问题。</p><p><strong>产品应用</strong>: 可以应用到智能家居、个人助理等产品中，通过智能触发器自动执行任务。</p><p><strong>示例场景</strong>: 智能助手根据温度自动为宠物狗加水。</p><hr><h3 id="_5-提示工程-新兴的用户体验技能" tabindex="-1">5. 提示工程：新兴的用户体验技能 <a class="header-anchor" href="#_5-提示工程-新兴的用户体验技能" aria-label="Permalink to &quot;5. 提示工程：新兴的用户体验技能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@katyneale/prompt-engineering-is-the-new-ux-skill-b3a58cb00e14" target="_blank" rel="noreferrer">Prompt Engineering is the New UX Skill | by Designed to Diverge</a></p><p><strong>一句话摘要</strong>: 通过界面设计和逐步披露改善AI提示，提升用户与AI的互动质量。</p><p><strong>能解决什么问题</strong>: 不同用户对AI的提示方式差异大，导致AI响应效果不一。</p><p><strong>产品应用</strong>: 适用于需要用户与AI深度交互的复杂企业环境，通过设计更好的提示引导用户。</p><p><strong>示例场景</strong>: 心脏外科医生和软件工程师使用同一AI工具时，需要不同的提示方法。</p><hr><h3 id="_6-主动性用户体验时代" tabindex="-1">6. 主动性用户体验时代 <a class="header-anchor" href="#_6-主动性用户体验时代" aria-label="Permalink to &quot;6. 主动性用户体验时代&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/the-agentic-era-of-ux-4b58634e410b" target="_blank" rel="noreferrer">The agentic era of UX</a></p><p><strong>一句话摘要</strong>: 主动性UX通过内置AI代理减轻用户的认知、创造和物流负担。</p><p><strong>能解决什么问题</strong>: 解决用户在数字体验中需要独立完成思考、规划和导航的问题。</p><p><strong>产品应用</strong>: 可应用于需要用户分析、决策和操作支持的软件产品，如数据分析平台。</p><p><strong>示例场景</strong>: 用户通过Dovetail平台上传访谈数据，AI帮助分析和整理。</p><hr><h3 id="_7-从产品到系统-代理型ai的转变" tabindex="-1">7. 从产品到系统：代理型AI的转变 <a class="header-anchor" href="#_7-从产品到系统-代理型ai的转变" aria-label="Permalink to &quot;7. 从产品到系统：代理型AI的转变&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/from-products-to-systems-the-agentic-ai-shift-eaf6a7180c43" target="_blank" rel="noreferrer">From products to systems: The agentic AI shift - UX Collective</a></p><p><strong>一句话摘要</strong>: 设计需适应人类与代理型AI的协作。</p><p><strong>能解决什么问题</strong>: 如何确保代理型AI在企业平台中与人类有效协作。</p><p><strong>产品应用</strong>: 适用于企业平台，通过设计系统使代理与人类协同工作。</p><p><strong>示例场景</strong>: DataRobot探索将设计文件转化为代理可理解的格式。</p><hr><h3 id="_8-以人工智能设计-用户体验考量与最佳实践" tabindex="-1">8. 以人工智能设计：用户体验考量与最佳实践 <a class="header-anchor" href="#_8-以人工智能设计-用户体验考量与最佳实践" aria-label="Permalink to &quot;8. 以人工智能设计：用户体验考量与最佳实践&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@mariamargarida/designing-with-ai-ux-considerations-and-best-practices-5c6b69b92c4c" target="_blank" rel="noreferrer">Designing with AI: UX Considerations and Best Practices</a></p><p><strong>一句话摘要</strong>: AI功能应根据需要选择隐藏或明确展示，以优化用户体验。</p><p><strong>能解决什么问题</strong>: 如何平衡AI的可见性与用户期望，提高交互效率。</p><p><strong>产品应用</strong>: 适用于需要AI辅助的产品，如智能助手，通过教育用户区分AI类型提升信任。</p><p><strong>示例场景</strong>: 智能客服中明确告知用户AI与人类的不同。</p><hr><h3 id="_9-设计师作为协调者-不确定的ai-使用cursor设计工具-以及ux如何影响损益表" tabindex="-1">9. 设计师作为协调者，不确定的AI，使用Cursor设计工具，以及UX如何影响损益表 <a class="header-anchor" href="#_9-设计师作为协调者-不确定的ai-使用cursor设计工具-以及ux如何影响损益表" aria-label="Permalink to &quot;9. 设计师作为协调者，不确定的AI，使用Cursor设计工具，以及UX如何影响损益表&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/designers-as-orchestrators-uncertain-ai-designing-with-cursor-how-ux-impacts-p-l-557ef6c89e62" target="_blank" rel="noreferrer">Designers as orchestrators, uncertain AI, designing with Cursor, how UX impacts P&amp;L</a></p><p><strong>一句话摘要</strong>: 探讨设计师在现代工具和AI影响下的角色变化及其对业务的直接影响。</p><p><strong>能解决什么问题</strong>: 解决设计师如何适应AI带来的工作变化和提高业务绩效的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI工具提高设计效率和业务收益。</p><p><strong>示例场景</strong>: 使用Cursor设计工具优化用户界面，提升产品用户体验。</p><hr><h3 id="_10-设计提示而非仅文字-将流程转化为提示" tabindex="-1">10. 设计提示而非仅文字：将流程转化为提示 <a class="header-anchor" href="#_10-设计提示而非仅文字-将流程转化为提示" aria-label="Permalink to &quot;10. 设计提示而非仅文字：将流程转化为提示&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/design-the-prompt-not-just-the-words-turning-flows-into-prompts-d2c53dc0a38e" target="_blank" rel="noreferrer">Design the prompt, not just the words: turning flows into prompts</a></p><p><strong>一句话摘要</strong>: 将用户流程转化为明确的提示，提升设计和可维护性</p><p><strong>能解决什么问题</strong>: 传统流程设计缺乏明确的步骤和状态管理</p><p><strong>产品应用</strong>: 适用于需要清晰用户流程和状态管理的产品</p><p><strong>示例场景</strong>: 在线购物平台的结账流程设计</p><hr>',75)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
